# panel
PANEL_HTML = r"""<style>
  body { margin: 0; padding: 10px 12px 16px; font-size: 13px; line-height: 1.35; }
  h3 { margin: 0; font-size: 14px; }
  .row { display: flex; align-items: center; gap: 6px; }
  .spread { justify-content: space-between; }
  .muted { color: var(--orca-muted); }
  .small { font-size: 12px; }
  button { cursor: pointer; }
  button.quiet { background: transparent; color: var(--orca-fg); border: 1px solid var(--orca-border); }
  button.danger { background: #c0392b; border-color: #c0392b; color: #fff; }
  button:disabled { opacity: .45; cursor: default; }
  .box { border: 1px solid var(--orca-border); border-radius: 6px; padding: 8px 10px; margin-top: 8px; }
  .job-name { font-weight: 600; word-break: break-all; }
  .warn { color: #c77700; }
  .err { color: #d0392b; }
  .ok { color: #2a9d55; }
  .dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; background: #999; flex: none; }
  .dot.idle { background: #2a9d55; } .dot.printing { background: #2f7de1; } .dot.paused { background: #c77700; }
  .dot.error { background: #d0392b; } .dot.offline { background: #888; } .dot.busy { background: #c77700; }
  .card-title { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .bar { height: 5px; background: var(--orca-border); border-radius: 3px; overflow: hidden; margin: 5px 0 3px; }
  .bar > i { display: block; height: 100%; background: var(--orca-accent); width: 0; }
  .actions { display: flex; gap: 6px; margin-top: 7px; flex-wrap: wrap; }
  .file { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .group { margin: 14px 0 0; font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: var(--orca-muted); }
  .group + .box { margin-top: 5px; }
  .slim { padding: 6px 10px; cursor: pointer; }
  .type + .type { margin-top: 9px; padding-top: 9px; border-top: 1px solid var(--orca-border); }
  .icon { background: none; border: none; padding: 2px; margin: 0; line-height: 0; color: var(--orca-muted); border-radius: 4px; flex: none; }
  .icon:hover { color: var(--orca-fg); background: var(--orca-border); }
  .icon svg, .chev svg { width: 14px; height: 14px; display: block; pointer-events: none; }
  .chev { color: var(--orca-muted); line-height: 0; flex: none; }
  .linkish { background: none; border: none; padding: 0 2px; color: var(--orca-muted); font-size: 12px; text-decoration: underline; }
  label.field { display: block; margin-top: 8px; font-size: 12px; }
  label.field input, label.field select { display: block; width: 100%; box-sizing: border-box; margin-top: 3px; }
  #overlay { position: fixed; inset: 0; background: rgba(0,0,0,.45); display: none; align-items: flex-start; justify-content: center; padding-top: 30px; }
  #overlay.show { display: flex; }
  #dialog { background: var(--orca-bg); color: var(--orca-fg); border: 1px solid var(--orca-border); border-radius: 8px;
            padding: 14px; width: calc(100% - 44px); max-width: 360px; max-height: calc(100% - 60px); overflow: auto; }
  #dialog h4 { margin: 0 0 8px; font-size: 14px; }
  .dialog-actions { display: flex; justify-content: flex-end; gap: 6px; margin-top: 14px; flex-wrap: wrap; }
  .check { display: flex; gap: 6px; align-items: center; margin-top: 4px; }
  .check input { margin: 0; }
  ul.plain { margin: 6px 0 0; padding-left: 18px; }
</style>

<div class="row spread">
  <h3 style="white-space:nowrap">Farm Send</h3>
  <div class="row">
    <button type="button" class="quiet" id="btn-refresh" title="Ask every printer for its status now">Refresh</button>
    <button type="button" class="quiet" id="btn-import" title="Add printers from your OrcaSlicer printer presets">Import</button>
    <button type="button" class="quiet" id="btn-add" title="Add a printer by address">Add</button>
  </div>
</div>

<div class="box" id="job"></div>
<div id="multi" class="box" style="display:none"></div>
<div id="printers"></div>
<div class="box" id="storage" style="display:none;margin-top:14px"></div>
<p id="empty" class="muted" style="display:none">No printers yet. Use Import to pull them from your printer presets, or Add.</p>

<div id="overlay"><div id="dialog"></div></div>

<script>
(function () {
  var state = { printers: [], jobs: [], job_for: {}, status: {}, sends: {}, slicing: false,
                combos: [], types: [], current: null, combo_note: { text: "" }, can_switch: false,
                library: [], folders: [], orders: [], order_plates: {}, toolhead_names: ["", "", "", ""], storage: {}, cleanup: { mode: "age", days: 30, keep: 50, auto: false, text: "" } };
  var selected = {};
  var expanded = {};   // busy printers shown as a full card instead of one line
  var $ = function (id) { return document.getElementById(id); };

  function esc(value) {
    var span = document.createElement("span");
    span.textContent = value == null ? "" : String(value);
    // Also safe inside quoted attributes: names and file names come from presets and printers.
    return span.innerHTML.replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function duration(seconds) {
    if (seconds == null) return "";
    seconds = Math.max(0, Math.round(seconds));
    var h = Math.floor(seconds / 3600), m = Math.floor((seconds % 3600) / 60);
    return h > 0 ? h + "h " + (m < 10 ? "0" : "") + m + "m" : m + "m";
  }
  function temp(value) {
    if (!value) return "";
    return Math.round(value.current) + (value.target ? "/" + Math.round(value.target) : "") + "°";
  }
  function swatch(color) {
    if (!/^#[0-9a-fA-F]{6}$/.test(color || "")) return "";
    return "<span style='display:inline-block;width:10px;height:10px;border-radius:2px;border:1px solid var(--orca-border);" +
           "vertical-align:-1px;margin-right:4px;background:" + color + "'></span>";
  }
  function filamentLines(job) {
    return (job.filaments || []).map(function (f) {
      return "<div class='small file'>Toolhead " + f.slot + " " + swatch(f.color) + esc(f.preset || f.type || "") +
             " <span class='muted'>· " + f.grams + " g</span></div>";
    }).join("");
  }
  function colorGap(a, b) {
    if (!/^#[0-9a-fA-F]{6}$/.test(a || "") || !/^#[0-9a-fA-F]{6}$/.test(b || "")) return 0;
    var total = 0;
    for (var i = 1; i < 7; i += 2) total += Math.abs(parseInt(a.substr(i, 2), 16) - parseInt(b.substr(i, 2), 16));
    return total;
  }
  // What the printer says is loaded in the toolheads this plate uses, and whether it disagrees.
  function loadedNote(printer, job) {
    var status = state.status[printer.id] || {}, tools = status.tools || [], notes = [];
    if (!tools.length) return "";
    (job.filaments || []).forEach(function (f) {
      var tool = tools.filter(function (x) { return x.slot === f.slot; })[0];
      if (!tool) { notes.push("<span class='warn'>no toolhead " + f.slot + "</span>"); return; }
      if (!tool.loaded) { notes.push("<span class='warn'>toolhead " + f.slot + " reports no filament</span>"); return; }
      var differs = colorGap(tool.color, f.color) > 90 || (tool.type && f.type && tool.type.toUpperCase() !== f.type.toUpperCase());
      notes.push((differs ? "<span class='warn'>" : "<span class='muted'>") + "toolhead " + f.slot + " has " + swatch(tool.color) +
                 esc(tool.type || "?") + (differs ? ", plate wants " + swatch(f.color) + esc(f.type || "") : "") + "</span>");
    });
    return notes.length ? "<div class='small'>" + notes.join(", ") + "</div>" : "";
  }
  // ---- refresh and clock times --------------------------------------------------------------
  var refreshing = {};   // printer id -> true from a Refresh click until that printer answers
  function refresh(ids) {
    ids.forEach(function (id) { refreshing[id] = true; });
    renderPrinters();
    send("refresh", ids.length === 1 ? { id: ids[0] } : {});
    // A printer that never answers must not leave its card stuck on "Checking...".
    setTimeout(function () { ids.forEach(function (id) { delete refreshing[id]; }); renderPrinters(); }, 40000);
  }
  function clock(date, seconds) {
    var options = { hour: "numeric", minute: "2-digit" };
    if (seconds) options.second = "2-digit";
    return date.toLocaleTimeString([], options);
  }
  function finishAt(remaining) {
    var now = new Date(), end = new Date(now.getTime() + remaining * 1000);
    var days = Math.round((new Date(end.getFullYear(), end.getMonth(), end.getDate()) -
                           new Date(now.getFullYear(), now.getMonth(), now.getDate())) / 86400000);
    var day = days === 0 ? "" : days === 1 ? " tomorrow" : " " + end.toLocaleDateString([], { weekday: "short" });
    return "done ~" + clock(end, false) + day;
  }

  // Icons are drawn here, not taken from a font, so they look the same on every system.
  var ICONS = {
    refresh: "<path d='M13 8a5 5 0 1 1-1.5-3.6'/><path d='M13 2.5v3h-3'/>",
    plus: "<path d='M8 3.5v9'/><path d='M3.5 8h9'/>",
    edit: "<path d='M2.5 13.5l.6-2.9 7.6-7.6 2.3 2.3-7.6 7.6z'/><path d='M9.4 4.3l2.3 2.3'/>",
    up: "<path d='M3.5 10l4.5-4.5 4.5 4.5'/>",
    down: "<path d='M3.5 6l4.5 4.5 4.5-4.5'/>",
    trash: "<path d='M3 4.5h10'/><path d='M6.5 4.5V3h3v1.5'/><path d='M4.5 4.5l.6 8.5h5.8l.6-8.5'/>"
  };
  function svg(name) {
    return "<svg viewBox='0 0 16 16' fill='none' stroke='currentColor' stroke-width='1.6' stroke-linecap='round' " +
           "stroke-linejoin='round' aria-hidden='true'>" + ICONS[name] + "</svg>";
  }
  // A small icon button. The hint doubles as the label for screen readers.
  function iconButton(name, attribute, id, hint) {
    return "<button type='button' class='icon' " + attribute + "='" + esc(id) + "' title='" + esc(hint) + "' aria-label='" + esc(hint) + "'>" +
           svg(name) + "</button>";
  }

  function send(command, extra) {
    var message = extra || {};
    message.command = command;
    orca.postMessage(message);
  }

  // ---- dialogs -----------------------------------------------------------------------------
  function showDialog(html) { $("dialog").innerHTML = html; $("overlay").className = "show"; }
  function hideDialog() { $("overlay").className = ""; $("dialog").innerHTML = ""; }
  $("overlay").addEventListener("click", function (event) { if (event.target === $("overlay")) hideDialog(); });

  function jobOf(printer) {
    var id = state.job_for[printer.id];
    if (!id) return null;
    return state.jobs.filter(function (j) { return j.id === id && j.ready; })[0] || null;
  }
  function blockReason(printer, start) {
    var job = jobOf(printer), status = state.status[printer.id];
    if (!job) {
      var ready = state.jobs.filter(function (j) { return j.ready; });
      if (ready.length) return "No plate sliced for " + printer.model + " yet";
      if (state.jobs.length && !state.jobs[0].error) return "Reading the sliced G-code";
      return "Slice a plate first";
    }
    if (state.sends[printer.id] && state.sends[printer.id].active) return "Send in progress";
    if (!status || status.state === "unknown") return "Checking printer";
    if (status.state === "offline") return "Printer is offline";
    if (start && status.state !== "idle") return "Printer is " + (status.state_text || status.state).toLowerCase();
    if (start && status.needs_clearing) return "Clear the bed, then click Bed cleared";
    return "";
  }

  function confirmSend(printers, start) {
    // Group the printers by the plate each one will receive: one plate per printer type.
    var groups = [], seen = {};
    printers.forEach(function (p) {
      var job = jobOf(p);
      if (!job) return;
      if (!(job.id in seen)) { seen[job.id] = groups.length; groups.push({ job: job, printers: [] }); }
      groups[seen[job.id]].printers.push(p);
    });
    var body = groups.map(function (g) {
      var notes = "";
      if (g.job.stale) notes += "<div class='warn small'>The plate changed after this slice. Re-slice if the change matters.</div>";
      if (g.job.post_process) notes += "<div class='warn small'>Post-processing scripts are not applied to this file.</div>";
      return "<div class='box' style='margin-top:8px'><div class='job-name small'>" + esc(g.job.display_name) + "</div>" +
        "<div class='muted small'>" + esc(g.job.summary) + " · for " + esc(g.job.printer_model) + "</div>" + notes +
        filamentLines(g.job) +
        "<ul class='plain'>" + g.printers.map(function (p) {
          return "<li>" + esc(p.name) + " <span class='muted'>(" + esc(p.address) + ")</span>" + loadedNote(p, g.job) + "</li>";
        }).join("") + "</ul></div>";
    }).join("");
    var options = "";
    if (start) {
      var anyU1 = printers.some(function (p) { return p.kind === "moonraker"; });
      options = "<div class='check' style='margin-top:8px'><input type='checkbox' id='opt-level' checked><label for='opt-level'>Bed leveling before print</label></div>" +
                (anyU1 ? "<div class='check'><input type='checkbox' id='opt-flow'><label for='opt-flow'>Flow calibration (Snapmaker)</label></div>" : "") +
                "<div class='check'><input type='checkbox' id='opt-lapse'><label for='opt-lapse'>Time-lapse</label></div>";
    }
    showDialog(
      "<h4>" + (start ? "Start printing?" : "Upload?") + "</h4>" +
      "<p style='margin:0'>" + (start ? "Each print starts immediately." : "Files are uploaded, not printed.") +
      (groups.length > 1 ? " Each printer gets the plate sliced for its type." : "") + "</p>" + body + options +
      (start ? "<p class='small muted'>Make sure each bed is clear.</p>" : "") +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button>" +
      "<button type='button' id='dlg-ok'" + (start ? " class='danger'" : "") + ">" + (start ? "Start print" : "Upload") + "</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      var options = { bed_leveling: $("opt-level") ? $("opt-level").checked : true,
                      flow_calibrate: $("opt-flow") ? $("opt-flow").checked : false,
                      timelapse: $("opt-lapse") ? $("opt-lapse").checked : false };
      send("send", { printer_ids: printers.map(function (p) { return p.id; }), start: start, options: options });
      hideDialog();
    };
  }

  function editPrinter(printer) {
    var p = printer || { id: "", name: "", kind: "moonraker", address: "", model: "", access_code: "", api_key: "" };
    showDialog(
      "<h4>" + (printer ? "Edit printer" : "Add printer") + "</h4>" +
      "<label class='field'>Name<input id='f-name' value='" + esc(p.name) + "' placeholder='U1 #3'></label>" +
      "<label class='field'>Type<select id='f-kind'>" +
        "<option value='moonraker'>Snapmaker U1 / Moonraker</option>" +
        "<option value='elegoo_cc2'>Elegoo Centauri Carbon 2</option></select></label>" +
      "<label class='field'>IP address or host name<input id='f-address' value='" + esc(p.address) + "' placeholder='192.168.1.50'></label>" +
      "<label class='field' id='row-code'>Access code<input id='f-code' value='" + esc(p.access_code) + "' placeholder='shown on the printer screen'></label>" +
      "<label class='field' id='row-key'>API key (leave empty if none)<input id='f-key' value='" + esc(p.api_key) + "'></label>" +
      "<label class='field'>Printer model<input id='f-model' value='" + esc(p.model) + "' placeholder='filled in by Test connection'></label>" +
      "<p class='small muted' style='margin:6px 0 0'>Only G-code sliced for this model can be sent here.</p>" +
      "<p class='small' id='f-result' style='min-height:16px;margin:8px 0 0'></p>" +
      "<div class='dialog-actions'>" +
        (printer ? "<button type='button' class='quiet' id='dlg-delete' style='margin-right:auto'>Remove</button>" : "") +
        "<button type='button' class='quiet' id='dlg-test'>Test connection</button>" +
        "<button type='button' class='quiet' id='dlg-cancel'>Cancel</button>" +
        "<button type='button' id='dlg-ok'>Save</button></div>");
    $("f-kind").value = p.kind;
    function sync() {
      var cc2 = $("f-kind").value === "elegoo_cc2";
      $("row-code").style.display = cc2 ? "block" : "none";
      $("row-key").style.display = cc2 ? "none" : "block";
    }
    function collect() {
      return { id: p.id, name: $("f-name").value, kind: $("f-kind").value, address: $("f-address").value,
               model: $("f-model").value, access_code: $("f-code").value, api_key: $("f-key").value };
    }
    $("f-kind").onchange = sync; sync();
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-test").onclick = function () {
      $("f-result").className = "small muted"; $("f-result").textContent = "Testing...";
      send("test_printer", { printer: collect() });
    };
    $("dlg-ok").onclick = function () {
      $("f-result").className = "small muted"; $("f-result").textContent = "Saving...";
      send("save_printer", { printer: collect() });
    };
    if (printer) $("dlg-delete").onclick = function () {
      showDialog("<h4>Remove " + esc(p.name) + "?</h4><p class='small muted'>Only removes it from this panel.</p>" +
        "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button>" +
        "<button type='button' class='danger' id='dlg-ok'>Remove</button></div>");
      $("dlg-cancel").onclick = hideDialog;
      $("dlg-ok").onclick = function () { send("delete_printer", { id: p.id }); hideDialog(); };
    };
  }

  // ---- rendering ---------------------------------------------------------------------------
  // Plates: one row per printer type, with the plate held for it or a way to slice one.
  function plateFor(type) {
    return state.jobs.filter(function (j) { return j.ready && j.key === type.key; })[0] || null;
  }
  function plateHtml(job) {
    return "<div class='job-name'>" + esc(job.display_name) + "</div>" +
      "<div class='muted small'>" + esc(job.summary) + " \u00b7 sliced " + esc(job.sliced_at) + "</div>" +
      filamentLines(job) +
      (job.presets ? "<div class='muted small file' title='" + esc(job.presets) + "'>" + esc(job.presets) + "</div>" : "") +
      (job.stale ? "<div class='warn small'>Plate changed since this slice. Slice again if this type should get the change.</div>" : "") +
      (job.post_process ? "<div class='warn small'>Post-processing scripts are not applied.</div>" : "") +
      (job.stale ? "" : "<div style='margin-top:6px'><button type='button' class='quiet' data-lib-save='" + esc(job.id) +
                       "' title='Keep this plate so it can be sent again later without slicing'>Save to library</button></div>");
  }

  // ---- library: plates kept for reprinting ---------------------------------------------------
  var plateView = "now", libQuery = "", libNote = null, libLastFolder = "";
  // Orders are switched off for now: whole-plate planning did not match how orders are split
  // (a few parts per printer). The code stays; set this to true to show the tab again.
  var ORDERS_ENABLED = false;
  function libraryListHtml() {
    var words = libQuery.toLowerCase().split(/\s+/).filter(Boolean);
    var entries = state.library.filter(function (e) {
      var text = (e.item + " " + e.printer_model + " x" + e.parts).toLowerCase();
      return words.every(function (w) { return text.indexOf(w) >= 0; });
    });
    if (!state.library.length) return "<div class='muted small' style='margin-top:6px'>Nothing kept yet. Slice a plate, then click \u201csave to library\u201d on its row.</div>";
    if (!entries.length) return "<div class='muted small' style='margin-top:6px'>No item matches.</div>";
    var row = function (e) {
      var saved = e.saved_at ? new Date(e.saved_at * 1000).toLocaleDateString([], { month: "short", day: "numeric" }) : "";
      return "<div class='type'><div class='row spread' style='gap:8px'>" +
        "<div class='file'><b>" + esc(e.item) + "</b> <span class='muted'>x" + esc(e.parts) + "</span></div>" +
        "<div class='row' style='flex:none'><button type='button' class='quiet' data-lib-send='" + esc(e.id) + "'" +
          (e.printers.length ? "" : " disabled") + ">Send</button>" + iconButton("edit", "data-lib-edit", e.id, "Rename, change the count or move to a folder") +
          iconButton("trash", "data-lib-del", e.id, "Remove from the library") + "</div></div>" +
        "<div class='muted small file'>" + esc(e.printer_model || "unknown printer") + " \u00b7 " + esc(e.summary) + (saved ? " \u00b7 kept " + esc(saved) : "") + "</div>" +
        filamentLines(e) +
        (e.presets ? "<div class='muted small file' title='" + esc(e.presets) + "'>" + esc(e.presets) + "</div>" : "") +
        (e.printers.length ? "" : "<div class='warn small'>No printer of this type is set up.</div>") + "</div>";
    };
    // Grouped by folder; plates in no folder come first. A search opens every folder it finds something in.
    // A tree by folder path ("Clips / Vertical"). Plates in no folder come first, untitled.
    var by = {}, shown = {};
    entries.forEach(function (e) { var f = e.folder || ""; (by[f] = by[f] || []).push(e); });
    var paths = words.length ? [] : state.folders.slice();          // a search shows only folders with a match
    Object.keys(by).forEach(function (f) {
      var parts = f ? f.split(SEP) : [];
      for (var d = 1; d <= parts.length; d++) { var up = parts.slice(0, d).join(SEP); if (paths.indexOf(up) < 0) paths.push(up); }
    });
    if (!paths.length) return (by[""] || []).map(row).join("");
    var inside = function (f) { return entries.filter(function (e) { return e.folder === f || (e.folder || "").indexOf(f + SEP) === 0; }).length; };
    var kids = function (parent) {
      return paths.filter(function (f) { var cut = f.lastIndexOf(SEP); return (cut < 0 ? "" : f.slice(0, cut)) === parent; })
                  .sort(function (a, b) { return a.toLowerCase() < b.toLowerCase() ? -1 : 1; });
    };
    var node = function (f) {
      var open = words.length > 0 || !libClosed[f], leaf = f.slice(f.lastIndexOf(SEP) < 0 ? 0 : f.lastIndexOf(SEP) + SEP.length);
      var depth = f.split(SEP).length, body = kids(f).map(node).join("") + (by[f] || []).map(row).join("");
      return "<div class='type'><div class='row spread' style='gap:6px'>" +
        "<button type='button' class='linkish file' style='padding:0;text-decoration:none;font-weight:600;color:inherit;text-align:left;min-width:0' data-lib-folder='" + esc(f) + "' title='" + esc(f) + "'>" +
        (open ? "\u25be " : "\u25b8 ") + esc(leaf) + " <span class='muted' style='font-weight:400;pointer-events:none'>(" + inside(f) + ")</span></button>" +
        "<div class='row' style='flex:none'>" + (depth < 4 ? iconButton("plus", "data-folder-new", f, "New folder inside this one") : "") +
          iconButton("edit", "data-folder-rename", f, "Rename this folder") +
          iconButton("trash", "data-folder-remove", f, "Remove this folder; what is in it is kept") + "</div></div>" +
        (open ? "<div style='margin:6px 0 0 9px'>" + (body || "<div class='muted small'>Empty. Move a plate here with its pencil, or pick this folder when you save one.</div>") + "</div>" : "") + "</div>";
    };
    return (by[""] || []).map(row).join("") + kids("").map(node).join("");
  }
  var SEP = " / ";
  function libraryTools() {
    var link = function (attr, label, title) {
      return "<button type='button' class='linkish' style='white-space:nowrap' " + attr + (title ? " title='" + title + "'" : "") + ">" + label + "</button>";
    };
    return "<div class='row spread' style='margin-top:7px'><button type='button' class='quiet' style='white-space:nowrap' data-folder-new=''>New folder</button>" +
      link("data-tool-names='1'", "toolhead names", "Name what each toolhead position holds, e.g. Black") + "</div>" +
      (state.folders.length ? "<div class='row' style='gap:10px;margin-top:5px;justify-content:flex-end'>" +
        link("data-folders-all='open'", "expand all") + link("data-folders-all='closed'", "collapse all") + "</div>" : "");
  }
  // old: full path of the folder to rename, or "" for a new one made inside parent ("" = top level).
  function folderDialog(old, parent) {
    var cut = old.lastIndexOf(SEP), home = old ? (cut < 0 ? "" : old.slice(0, cut)) : (parent || "");
    showDialog("<h4>" + (old ? "Rename folder" : "New folder") + "</h4>" +
      (home ? "<p class='small muted' style='margin:0'>Inside " + esc(home) + "</p>" : "") +
      "<label class='field'>Folder name<input id='f-name' maxlength='40' value='" + esc(old ? old.slice(cut < 0 ? 0 : cut + SEP.length) : "") + "'></label>" +
      "<p class='small' id='l-result' style='min-height:16px;margin:8px 0 0'></p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>" + (old ? "Rename" : "Create") + "</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      var leaf = $("f-name").value.replace(/\//g, " ").trim();        // "/" separates levels, so not inside a name
      if (!leaf) { $("f-name").focus(); return; }
      var full = (home ? home + SEP : "") + leaf;
      send("library_folder", old ? { action: "rename", name: old, new: full } : { action: "add", name: full });
    };
    $("f-name").focus();
  }
  var libClosed = {};
  function folderField(current) {
    var names = state.folders.slice();
    if (current && names.indexOf(current) < 0) names.push(current);
    return "<label class='field'>Folder<select id='l-folder'><option value=''>No folder</option>" + names.map(function (n) {
      return "<option value='" + esc(n) + "'" + (n === current ? " selected" : "") + ">" + esc(n) + "</option>"; }).join("") + "</select></label>" +
      (names.length ? "" : "<div class='small muted' style='margin-top:3px'>Make folders with New folder in the Library view.</div>");
  }
  function wireFolderPicks() {}
  function editLibrary(id) {
    var e = state.library.filter(function (x) { return x.id === id; })[0];
    if (!e) return;
    showDialog("<h4>Edit library plate</h4>" +
      "<label class='field'>Item name<input id='l-item' value='" + esc(e.item) + "'></label>" +
      "<label class='field'>Parts on this plate<input id='l-parts' type='number' min='1' max='9999' value='" + esc(e.parts) + "'></label>" +
      folderField(e.folder) +
      "<p class='small muted' style='margin:8px 0 0'>An open order finds its plates by item name, so renaming an item detaches it from that order.</p>" +
      "<p class='small' id='l-result' style='min-height:16px;margin:8px 0 0'></p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>Save</button></div>");
    wireFolderPicks();
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      send("library_edit", { id: id, item: $("l-item").value, parts: $("l-parts").value, folder: $("l-folder").value });
    };
  }

  // ---- orders: a quantity of one item, worked off plate by plate -------------------------------
  function toolLabel(n) { var name = state.toolhead_names[n - 1]; return n + (name ? " \u2014 " + name : ""); }
  function ordersHtml() {
    var html = "<div class='row spread' style='margin-top:7px'><button type='button' class='quiet' data-order-new='1'" +
      (state.library.length ? "" : " disabled") + ">New order</button>" +
      "<button type='button' class='linkish' data-tool-names='1' title='Name what each toolhead position holds, e.g. Black'>toolhead names</button></div>";
    if (!state.library.length) return html + "<div class='muted small' style='margin-top:6px'>Orders print plates from the library. Save a plate there first.</div>";
    if (!state.orders.length) return html + "<div class='muted small' style='margin-top:6px'>No open orders. An order is a quantity of one library item; the panel proposes plates for the free printers and keeps count.</div>";
    return html + state.orders.map(function (o) {
      var done = o.remaining === 0 && o.printing === 0;
      var bits = [o.good + " good"];
      if (o.printing) bits.push(o.printing + " printing");
      bits.push(done ? "complete" : o.remaining + " to start");
      var where = o.plates.filter(function (p) { return p.state === "printing"; }).map(function (p) { return p.printer_name + " x" + p.parts; }).join(", ");
      return "<div class='type'><div class='row spread' style='gap:8px'>" +
        "<div class='file'><b>" + esc(o.item) + "</b> <span class='muted'>" + esc(o.quantity) + " wanted</span></div>" +
        "<div class='row' style='flex:none'><button type='button' class='quiet' data-order-plan='" + esc(o.id) + "'" +
          (o.remaining && o.in_library ? "" : " disabled") + ">Print next</button>" + iconButton("trash", "data-order-del", o.id, done ? "Close this order" : "Delete this order") + "</div></div>" +
        "<div class='small " + (done ? "ok" : "muted") + "'>" + esc(bits.join(" \u00b7 ")) + "</div>" +
        ((o.toolhead || o.note) ? "<div class='small muted file'>" + esc((o.toolhead ? "Toolhead " + toolLabel(o.toolhead) : "") + (o.toolhead && o.note ? " \u00b7 " : "") + o.note) + "</div>" : "") +
        (where ? "<div class='small muted file'>On " + esc(where) + ". Counted when you click Bed cleared.</div>" : "") +
        (o.in_library ? "" : "<div class='warn small'>This item is no longer in the library.</div>") + "</div>";
    }).join("");
  }
  function newOrder() {
    var items = [];
    state.library.forEach(function (e) { if (items.indexOf(e.item) < 0) items.push(e.item); });
    showDialog("<h4>New order</h4>" +
      "<label class='field'>Item<select id='o-item'>" + items.map(function (i) { return "<option>" + esc(i) + "</option>"; }).join("") + "</select></label>" +
      "<label class='field'>Quantity wanted<input id='o-qty' type='number' min='1' max='99999'></label>" +
      "<label class='field'>Toolhead on Snapmaker printers<select id='o-tool'><option value=''>as sliced</option>" +
        [1, 2, 3, 4].map(function (n) { return "<option value='" + n + "'>" + esc(toolLabel(n)) + "</option>"; }).join("") + "</select></label>" +
      "<label class='field'>Note (optional)<input id='o-note' maxlength='60' placeholder='e.g. white, order 1234'></label>" +
      "<p class='small muted' style='margin:8px 0 0'>The toolhead applies to one-filament plates. Other printers print from whatever is loaded.</p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>Create</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      if (!(parseInt($("o-qty").value, 10) > 0)) { $("o-qty").focus(); return; }
      send("order_save", { item: $("o-item").value, quantity: $("o-qty").value, toolhead: $("o-tool").value, note: $("o-note").value });
      hideDialog();
    };
    $("o-qty").focus();
  }
  function toolheadNames() {
    showDialog("<h4>Toolhead names</h4><p class='small muted' style='margin:0'>What each toolhead position holds on your printers, if you keep them the same. Shown wherever a toolhead is picked. Only a label: nothing is checked against it.</p>" +
      [1, 2, 3, 4].map(function (n) { return "<label class='field'>Toolhead " + n + "<input id='tn-" + n + "' maxlength='20' value='" + esc(state.toolhead_names[n - 1] || "") + "'></label>"; }).join("") +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>Save</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      send("save_toolhead_names", { names: [1, 2, 3, 4].map(function (n) { return $("tn-" + n).value; }) });
      hideDialog();
    };
  }
  function showPlan(message) {
    var o = state.orders.filter(function (x) { return x.id === message.id; })[0];
    if (!o) return;
    var entry = function (id) { return state.library.filter(function (e) { return e.id === id; })[0] || {}; };
    var name = function (id) { return (state.printers.filter(function (p) { return p.id === id; })[0] || {}).name || "printer"; };
    var kind = function (id) { return (state.printers.filter(function (p) { return p.id === id; })[0] || {}).kind; };
    if (!message.plan.length) {
      showDialog("<h4>" + esc(o.item) + ": nothing to start</h4><p class='small muted'>" +
        (message.remaining ? "No free printer can take this item right now. A printer is free when it is idle, its bed is cleared and it has no uncounted plate." : "Every part of this order is printed or printing.") +
        "</p><div class='dialog-actions'><button type='button' id='dlg-cancel'>OK</button></div>");
      $("dlg-cancel").onclick = hideDialog;
      return;
    }
    var anyU1 = message.plan.some(function (x) { return kind(x.printer_id) === "moonraker"; });
    var anyOther = message.plan.some(function (x) { return kind(x.printer_id) !== "moonraker"; });
    showDialog("<h4>" + esc(o.item) + ": " + esc(message.remaining) + " to start</h4>" +
      message.plan.map(function (x, i) {
        var e = entry(x.entry_id), p = state.printers.filter(function (q) { return q.id === x.printer_id; })[0] || {};
        return "<div class='check' style='align-items:flex-start;margin-top:7px'><input type='checkbox' checked data-pick='" + i + "' id='pk-" + i + "' style='margin-top:2px'>" +
          "<label for='pk-" + i + "' style='min-width:0'>" + esc(name(x.printer_id)) + " <span class='muted small'>x" + esc(x.parts) + " \u00b7 " + esc(e.summary || "") + "</span>" + toolsHtml(p) + "</label></div>";
      }).join("") +
      (anyU1 && o.toolhead ? "<p class='small' style='margin:10px 0 0'>Snapmaker printers print from toolhead " + esc(toolLabel(o.toolhead)) + ".</p>" : "") +
      (anyOther ? "<p class='small warn' style='margin:6px 0 0'>Other printers print from whatever is loaded. Check the color yourself.</p>" : "") +
      "<div class='check' style='margin-top:10px'><input type='checkbox' id='opt-level' checked><label for='opt-level'>Bed leveling before print</label></div>" +
      (anyU1 ? "<div class='check'><input type='checkbox' id='opt-flow'><label for='opt-flow'>Flow calibration (Snapmaker)</label></div>" : "") +
      "<div class='check'><input type='checkbox' id='opt-lapse'><label for='opt-lapse'>Time-lapse</label></div>" +
      "<p class='small' id='l-total' style='margin:10px 0 0'></p>" +
      "<p class='small muted' style='margin:4px 0 0'>Each print starts immediately. Make sure each bed is clear.</p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' class='danger' id='dlg-ok'>Start prints</button></div>");
    function picks() {
      return Array.prototype.filter.call($("dialog").querySelectorAll("input[data-pick]"), function (b) { return b.checked; })
        .map(function (b) { return message.plan[parseInt(b.dataset.pick, 10)]; });
    }
    function total() {
      var chosen = picks(), parts = chosen.reduce(function (sum, x) { return sum + x.parts; }, 0), left = message.remaining - parts;
      $("l-total").textContent = chosen.length ? parts + " parts on " + chosen.length + " printer" + (chosen.length === 1 ? "" : "s") + ". " +
        (left > 0 ? left + " still to start after this." : left < 0 ? (-left) + " extra." : "That covers the order.") : "Tick at least one printer.";
      $("dlg-ok").disabled = !chosen.length;
    }
    $("dialog").onchange = total; total();
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      send("order_send", { id: o.id, picks: picks(), options: { bed_leveling: $("opt-level").checked,
        flow_calibrate: $("opt-flow") ? $("opt-flow").checked : false, timelapse: $("opt-lapse").checked } });
      hideDialog();
    };
  }
  function bedCleared(printerId) {
    var plate = state.order_plates[printerId];
    if (!plate) { send("bed_cleared", { id: printerId }); return; }
    var failed = (state.status[printerId] || {}).last_result !== "complete";
    showDialog("<h4>Bed cleared: how many good parts?</h4><p class='small muted' style='margin:0'>This plate was " + esc(plate.item) + " x" + esc(plate.parts) +
      ", printed for an order. Only good parts count toward it.</p>" +
      "<label class='field'>Good parts<input id='b-good' type='number' min='0' max='" + esc(plate.parts) + "' value='" + (failed ? 0 : esc(plate.parts)) + "'></label>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>Bed is clear</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      var good = parseInt($("b-good").value, 10);
      if (!(good >= 0)) { $("b-good").focus(); return; }
      send("bed_cleared", { id: printerId, good: Math.min(good, plate.parts) });
      hideDialog();
    };
    $("b-good").select();
  }
  function saveToLibrary(jobId) {
    var job = state.jobs.filter(function (j) { return j.id === jobId; })[0];
    if (!job) return;
    showDialog("<h4>Save to library</h4>" +
      "<p class='small muted' style='margin:0'>Keeps this sliced plate so you can send it again later without slicing. It is kept as sliced: for " +
        esc(job.printer_model) + ", with these settings.</p>" +
      "<label class='field'>Item name<input id='l-item' value='" + esc(job.display_name) + "'></label>" +
      "<label class='field'>Parts on this plate<input id='l-parts' type='number' min='1' max='9999' placeholder='count them, e.g. 24'></label>" +
      folderField(libLastFolder) +
      "<p class='small' id='l-result' style='min-height:16px;margin:8px 0 0'></p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>Save</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      $("l-result").className = "small muted"; $("l-result").textContent = "Saving...";
      libLastFolder = $("l-folder").value;
      send("library_save", { job_id: jobId, item: $("l-item").value, parts: $("l-parts").value, folder: libLastFolder });
    };
    wireFolderPicks();
    $("l-parts").focus();
  }
  function toolsHtml(printer) {
    var tools = (state.status[printer.id] || {}).tools || [];
    if (!tools.length) return "";
    return "<div class='small muted'>" + tools.map(function (t) {
      return t.slot + " " + (t.loaded ? swatch(t.color) + esc(t.type || "") : "empty");
    }).join(" \u00b7 ") + "</div>";
  }
  function sendFromLibrary(id) {
    var e = state.library.filter(function (x) { return x.id === id; })[0];
    if (!e) return;
    var printers = state.printers.filter(function (p) { return e.printers.indexOf(p.id) >= 0; });
    var anyU1 = printers.some(function (p) { return p.kind === "moonraker"; });
    var single = e.filaments.length === 1, sliced = single ? e.filaments[0].slot : 0;
    var rows = printers.map(function (p) {
      var st = state.status[p.id] || {}, free = st.state === "idle" && !st.needs_clearing;
      return "<div class='check' style='align-items:flex-start;margin-top:7px'><input type='checkbox' data-lp='" + esc(p.id) + "' id='lp-" + esc(p.id) + "'" +
        (free ? " checked" : "") + " style='margin-top:2px'><label for='lp-" + esc(p.id) + "' style='min-width:0'>" + esc(p.name) +
        " <span class='muted small'>" + esc(st.needs_clearing ? "clear the bed first" : (st.state_text || st.state || "checking")) + "</span>" + toolsHtml(p) + "</label></div>";
    }).join("");
    var pick = "";
    if (single && anyU1) {
      pick = "<label class='field'>Print from toolhead (Snapmaker)<select id='l-tool'><option value=''>" + sliced + " \u2014 as sliced</option>" +
        [1, 2, 3, 4].filter(function (n) { return n !== sliced; }).map(function (n) { return "<option value='" + n + "'>" + esc(toolLabel(n)) + "</option>"; }).join("") +
        "</select></label><p class='small muted' style='margin:4px 0 0'>The color is whatever that toolhead holds; each printer's toolheads are listed above. Material and temperatures stay as sliced.</p>";
    }
    showDialog("<h4>Send " + esc(e.item) + " x" + esc(e.parts) + "</h4>" +
      "<div class='muted small'>" + esc(e.summary) + " \u00b7 for " + esc(e.printer_model) + "</div>" + filamentLines(e) + rows + pick +
      "<div class='check' style='margin-top:10px'><input type='checkbox' id='opt-level' checked><label for='opt-level'>Bed leveling before print</label></div>" +
      (anyU1 ? "<div class='check'><input type='checkbox' id='opt-flow'><label for='opt-flow'>Flow calibration (Snapmaker)</label></div>" : "") +
      "<div class='check'><input type='checkbox' id='opt-lapse'><label for='opt-lapse'>Time-lapse</label></div>" +
      "<p class='small' id='l-total' style='margin:10px 0 0'></p>" +
      "<p class='small muted' style='margin:4px 0 0'>Each print starts immediately. Make sure each bed is clear.</p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button>" +
      "<button type='button' class='quiet' id='dlg-upload'>Upload only</button><button type='button' class='danger' id='dlg-ok'>Start print</button></div>");
    function picked() {
      return Array.prototype.filter.call($("dialog").querySelectorAll("input[data-lp]"), function (b) { return b.checked; }).map(function (b) { return b.dataset.lp; });
    }
    function total() {
      var n = picked().length;
      $("l-total").textContent = n ? n + " printer" + (n === 1 ? "" : "s") + " \u00d7 " + e.parts + " = " + (n * e.parts) + " parts" : "Tick at least one printer.";
      $("dlg-ok").disabled = $("dlg-upload").disabled = !n;
    }
    function go(start) {
      send("library_send", { id: id, printer_ids: picked(), start: start, toolhead: $("l-tool") && $("l-tool").value ? parseInt($("l-tool").value, 10) : null,
        options: { bed_leveling: $("opt-level").checked, flow_calibrate: $("opt-flow") ? $("opt-flow").checked : false, timelapse: $("opt-lapse").checked } });
      hideDialog();
    }
    $("dialog").onchange = total; total();
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-upload").onclick = function () { go(false); };
    $("dlg-ok").onclick = function () { go(true); };
  }
  function renderJob() {
    var note = state.combo_note || {}, busy = !!note.busy;
    var tab = function (name, label) {
      return "<button type='button' class='" + (plateView === name ? "" : "quiet") + "' style='padding:2px 8px;font-size:12px' data-view='" + name + "'>" + label + "</button>";
    };
    var html = "<div class='row spread'><span class='card-title'>Plates</span><span class='row' style='gap:4px'>" +
               tab("now", "Sliced now") + tab("library", "Library (" + state.library.length + ")") +
               (ORDERS_ENABLED ? tab("orders", "Orders (" + state.orders.length + ")") : "") + "</span></div>";
    if (libNote) html += "<div class='small " + (libNote.ok ? "ok" : "err") + "' style='margin-top:4px'>" + esc(libNote.text) + "</div>";
    if (plateView === "orders" && !ORDERS_ENABLED) plateView = "library";
    if (plateView === "orders") { $("job").innerHTML = html + ordersHtml(); return; }
    if (plateView === "library") {
      html += libraryTools() +
              "<input id='lib-search' type='search' placeholder='Search items' value='" + esc(libQuery) + "' style='width:100%;box-sizing:border-box;margin-top:7px'>" +
              "<div id='lib-list' style='margin-top:7px'>" + libraryListHtml() + "</div>";
      $("job").innerHTML = html;
      $("lib-search").oninput = function () { libQuery = this.value; $("lib-list").innerHTML = libraryListHtml(); };
      return;
    }
    if (state.slicing) html += "<div class='muted small' style='margin-top:4px'>Slicing...</div>";
    state.jobs.forEach(function (job) {   // a slice still being read, or one that could not be used
      if (!job.ready) html += "<div class='small " + (job.error ? "err" : "muted") + "' style='margin-top:4px'>" +
                              esc(job.error || "Reading the sliced G-code...") + "</div>";
    });
    if (!state.types.length) {
      html += "<div class='muted small' style='margin-top:4px'>Add your printers, then slice once for each printer type. " +
              "Every slice is kept here until you send it.</div>";
    }
    html += "<div style='margin-top:7px'>" + state.types.map(function (type) {
      var job = plateFor(type), combo = type.combo, action = "";
      if (combo && combo.active) action = "<span class='ok small'>in use</span>";
      else if (combo) action = "<button type='button' class='quiet' data-combo-load='" + esc(type.key) + "'" +
                               (busy || !state.can_switch ? " disabled" : "") +
                               " title='Switch OrcaSlicer to the printer, process and filament remembered for this type'>Use presets</button>";
      else if (type.selected) action = "<span class='muted small'>selected</span>";
      return "<div class='type'><div class='row spread' style='gap:8px'>" +
        "<div class='file'><b>" + esc(type.label) + "</b></div><div class='row' style='flex:none'>" + action + "</div></div>" +
        (job ? plateHtml(job) : "<div class='muted small'>Not sliced yet" +
               (combo ? (combo.active ? ". Slice the plate." : "") : ". Select its presets in OrcaSlicer and slice.") + "</div>") +
        "<div class='row spread small muted' style='gap:8px'><span class='file'>" +
          (type.printers.length ? esc(type.printers.join(", ")) : "no printers of this type") + "</span>" +
          "<button type='button' class='linkish' style='flex:none' data-type-presets='" + esc(type.key) + "'>presets</button></div></div>";
    }).join("") + "</div>";
    if (note.text) html += "<div class='small " + (note.ok ? "muted" : "err") + "' style='margin-top:6px'>" + esc(note.text) + "</div>";
    $("job").innerHTML = html;
  }

  // The presets remembered for one printer type: view, remember the current ones, forget.
  function presetsDialog(key) {
    var type = state.types.filter(function (t) { return t.key === key; })[0];
    if (!type) return;
    var combo = type.combo, current = state.current;
    var saved = combo
      ? "<div class='small'>Printer: " + esc(combo.printer) + "</div><div class='small'>Process: " + esc(combo.process) + "</div>" +
        "<div class='small'>Filament: " + esc(combo.filaments.join(", ") || "none") + "</div>"
      : "<div class='small muted'>Nothing remembered yet for this type.</div>";
    var canSave = type.selected && current && current.printer;
    showDialog("<h4>Presets for " + esc(type.label) + "</h4>" +
      "<p class='small muted' style='margin:0 0 6px'>Use presets switches OrcaSlicer to these in one click, so every slice for this type uses the same settings.</p>" +
      saved +
      "<p class='small muted' style='margin:10px 0 0'>" + (canSave
        ? "Selected in OrcaSlicer now: " + esc(current.printer) + " \u00b7 " + esc(current.process || "") + " \u00b7 " + esc((current.filaments || []).join(", "))
        : "To change them, select this printer type and the presets you want in OrcaSlicer first.") + "</p>" +
      "<div class='dialog-actions'>" +
        (combo ? "<button type='button' class='quiet' id='dlg-forget' style='margin-right:auto'>Forget</button>" : "") +
        "<button type='button' class='quiet' id='dlg-cancel'>Close</button>" +
        "<button type='button' id='dlg-ok'" + (canSave ? "" : " disabled") + ">Remember current</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () { send("save_combo"); hideDialog(); };
    if (combo) $("dlg-forget").onclick = function () { send("delete_combo", { key: key }); hideDialog(); };
  }

  $("job").addEventListener("click", function (event) {
    var d = event.target.dataset || {};
    if (d.view) { plateView = d.view; libNote = null; renderJob(); }
    else if (d.orderNew) newOrder();
    else if (d.toolNames) toolheadNames();
    else if (d.orderPlan) send("order_plan", { id: d.orderPlan });
    else if (d.orderDel) {
      var gone = state.orders.filter(function (x) { return x.id === d.orderDel; })[0];
      showDialog("<h4>Remove the order for " + esc(gone ? gone.quantity + " " + gone.item : "this item") + "?</h4>" +
        "<p class='small muted'>Its count is forgotten. Prints already running are not stopped.</p>" +
        "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' class='danger' id='dlg-ok'>Remove</button></div>");
      $("dlg-cancel").onclick = hideDialog;
      $("dlg-ok").onclick = function () { send("order_delete", { id: d.orderDel }); hideDialog(); };
    }
    else if (d.libSave) saveToLibrary(d.libSave);
    else if (d.libEdit) editLibrary(d.libEdit);
    else if (d.folderNew !== undefined) folderDialog("", d.folderNew);
    else if (d.folderRename) folderDialog(d.folderRename);
    else if (d.foldersAll) {
      libClosed = {};
      if (d.foldersAll === "closed") { libClosed[""] = true; state.folders.forEach(function (f) { libClosed[f] = true; }); }
      $("lib-list").innerHTML = libraryListHtml();
    }
    else if (d.folderRemove) {
      var held = state.library.filter(function (x) { return x.folder === d.folderRemove || (x.folder || "").indexOf(d.folderRemove + SEP) === 0; }).length;
      var subs = state.folders.filter(function (f) { return f.indexOf(d.folderRemove + SEP) === 0; }).length;
      showDialog("<h4>Remove the folder \u201c" + esc(d.folderRemove) + "\u201d?</h4>" +
        "<p class='small muted'>" + (held || subs ? "What is in it is kept and moves up one level: " + held + " plate" + (held === 1 ? "" : "s") +
          (subs ? " and " + subs + " folder" + (subs === 1 ? "" : "s") : "") + "." : "It is empty.") + " No G-code is deleted.</p>" +
        "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' class='danger' id='dlg-ok'>Remove folder</button></div>");
      $("dlg-cancel").onclick = hideDialog;
      $("dlg-ok").onclick = function () { send("library_folder", { action: "remove", name: d.folderRemove }); hideDialog(); };
    }
    else if (d.libFolder !== undefined) { libClosed[d.libFolder] = !libClosed[d.libFolder]; $("lib-list").innerHTML = libraryListHtml(); }
    else if (d.libSend) sendFromLibrary(d.libSend);
    else if (d.libDel) {
      var entry = state.library.filter(function (x) { return x.id === d.libDel; })[0];
      showDialog("<h4>Remove " + esc(entry ? entry.item + " x" + entry.parts : "this plate") + " from the library?</h4>" +
        "<p class='small muted'>The kept G-code is deleted from this computer. Files already on the printers stay.</p>" +
        "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' class='danger' id='dlg-ok'>Remove</button></div>");
      $("dlg-cancel").onclick = hideDialog;
      $("dlg-ok").onclick = function () { send("library_delete", { id: d.libDel }); hideDialog(); };
    }
    else if (d.comboLoad) send("load_combo", { key: d.comboLoad });
    else if (d.typePresets) presetsDialog(d.typePresets);
  });

  function renderMulti() {
    // "Available" here means it could start now: a plate for its type, idle, bed clear.
    var withPlate = state.printers.filter(function (p) { return jobOf(p) && !blockReason(p, true); });
    var chosen = state.printers.filter(function (p) { return selected[p.id]; });
    if (chosen.length < 2 && withPlate.length < 2) { $("multi").style.display = "none"; return; }
    $("multi").style.display = "block";
    var allPicked = withPlate.length > 0 && withPlate.every(function (p) { return selected[p.id]; });
    var html = "<div class='row spread'><span>" + (chosen.length ? chosen.length + " selected" : "Send to several printers") + "</span><span>" +
      (withPlate.length >= 2 && !allPicked ? "<button type='button' class='linkish' id='multi-all'>select all available (" + withPlate.length + ")</button>" : "") +
      (chosen.length ? "<button type='button' class='linkish' id='multi-clear'>clear</button>" : "") + "</span></div>";
    if (chosen.length >= 2) {
      var uploadBlocked = chosen.some(function (p) { return blockReason(p, false); });
      var startBlocked = chosen.some(function (p) { return blockReason(p, true); });
      html += "<div class='actions'><button type='button' class='quiet' id='multi-upload'" + (uploadBlocked ? " disabled" : "") + ">Upload to all</button>" +
        "<button type='button' id='multi-start'" + (startBlocked ? " disabled" : "") + ">Upload and print on all</button></div>";
      if (uploadBlocked) html += "<div class='muted small' style='margin-top:4px'>A selected printer has no plate sliced for its type, or is offline.</div>";
      else if (startBlocked) html += "<div class='muted small' style='margin-top:4px'>Print is available when every selected printer is idle with a clear bed.</div>";
    }
    $("multi").innerHTML = html;
    if ($("multi-all")) $("multi-all").onclick = function () { withPlate.forEach(function (p) { selected[p.id] = true; }); render(); };
    if ($("multi-clear")) $("multi-clear").onclick = function () { selected = {}; render(); };
    if ($("multi-upload")) $("multi-upload").onclick = function () { confirmSend(chosen, false); };
    if ($("multi-start")) $("multi-start").onclick = function () { confirmSend(chosen, true); };
  }

  // Which group a printer belongs in. Nothing is hidden: the groups only order the list.
  function groupOf(p) {
    var status = state.status[p.id];
    if (!status || status.state === "unknown") return "busy";
    if (status.state === "paused" || status.state === "error" || status.state === "offline") return "attention";
    if (status.state === "idle") return status.needs_clearing ? "attention" : "available";
    return "busy";
  }
  function progressText(status) {
    var pct = status.progress == null ? "" : Math.round(status.progress) + "%";
    if (status.remaining_s == null) return pct;
    return (pct ? pct + " \u00b7 " : "") + (status.state === "paused" ? duration(status.remaining_s) + " left" : finishAt(status.remaining_s));
  }
  function slimCard(p, status) {
    return "<div class='box slim' data-expand='" + esc(p.id) + "' title='Show details'>" +
      "<div class='row spread' data-expand='" + esc(p.id) + "'><div class='row' style='min-width:0' data-expand='" + esc(p.id) + "'>" +
        "<span class='dot " + esc(status.state) + "'></span><span class='card-title' data-expand='" + esc(p.id) + "'>" + esc(p.name) + "</span></div>" +
      "<div class='row' style='flex:none' data-expand='" + esc(p.id) + "'>" +
      "<span class='small muted' style='white-space:nowrap' data-expand='" + esc(p.id) + "'>" +
        esc(refreshing[p.id] ? "Checking..." : (status.state === "printing" ? progressText(status) || "Printing" : (status.state_text || status.state))) +
      "</span><span class='chev' data-expand='" + esc(p.id) + "'>" + svg("down") + "</span></div></div></div>";
  }
  function fullCard(p, status, group) {
    var sending = state.sends[p.id];
    var uploadWhy = blockReason(p, false), startWhy = blockReason(p, true);
    var lines = "";
    if (status.state === "printing" || status.state === "paused") {
      var pct = status.progress == null ? null : Math.round(status.progress);
      lines += "<div class='file small' title='" + esc(status.filename) + "'>" + esc(status.filename) + "</div>" +
               "<div class='bar'><i style='width:" + (pct || 0) + "%'></i></div>" +
               "<div class='row spread small muted'><span>" + (pct == null ? "" : pct + "%") + "</span><span>" +
               (status.remaining_s == null ? "" : duration(status.remaining_s) + " left \u00b7 " +
                 (status.state === "paused" ? "paused" : finishAt(status.remaining_s))) + "</span></div>";
    }
    var temps = [];
    if (status.nozzle) temps.push("Nozzle " + temp(status.nozzle));
    if (status.bed) temps.push("Bed " + temp(status.bed));
    var checked = status.checked_at ? "checked " + clock(new Date(status.checked_at * 1000), true) : "";
    if (temps.length || checked) lines += "<div class='row spread small muted' style='flex-wrap:wrap'><span>" + temps.join(" \u00b7 ") +
                                          "</span><span style='white-space:nowrap'>" + checked + "</span></div>";
    if (status.notice) lines += "<div class='small " + (status.notice.level === "error" ? "err" : "ok") + "'>" + esc(status.notice.text) +
                                " \u00b7 " + clock(new Date(status.notice.at * 1000), false) + "</div>";
    if (status.state === "offline" && status.detail) lines += "<div class='small muted'>" + esc(status.detail) + "</div>";
    var stored = state.storage[p.id];
    if (stored && stored.many) lines += "<div class='small warn'>" + stored.count + " stored files. Uploads to this printer can start failing: clean up below.</div>";
    if (status.needs_clearing) {
      lines += "<div class='row spread' style='margin-top:6px;gap:8px'><span class='warn small'>Take the finished print off the bed.</span>" +
               "<button type='button' class='quiet' style='flex:none' data-cleared='" + esc(p.id) + "'>Bed cleared</button></div>";
    }
    var sendLine = "";
    if (sending) {
      if (sending.active) {
        sendLine = "<div class='small'>" + esc(sending.text) + "</div><div class='bar'><i style='width:" + Math.round(sending.percent || 0) + "%'></i></div>" +
                   "<button type='button' class='linkish' data-cancel='" + esc(p.id) + "'>cancel</button>";
      } else {
        sendLine = "<div class='small " + (sending.ok ? "ok" : "err") + "'>" + esc(sending.text) + "</div>";
      }
    }
    var hint = "";
    if (!sending || !sending.active) {
      if (uploadWhy) hint = uploadWhy; else if (startWhy) hint = "Print: " + startWhy.charAt(0).toLowerCase() + startWhy.slice(1);
    }
    var stateText = refreshing[p.id] ? "Checking..." : (status.needs_clearing ? "Finished" : (status.state_text || status.state));
    // An opened busy card closes the way it opened: click its name or state. A ticked card stays
    // open, because the tick box only exists on the full card.
    var fold = group === "busy" && !selected[p.id] && !(sending && sending.active)
      ? " data-collapse='" + esc(p.id) + "' style='cursor:pointer' title='Collapse'" : "";
    return "<div class='box'>" +
      "<div class='row spread'><div class='row' style='min-width:0'>" +
        "<input type='checkbox' data-pick='" + esc(p.id) + "'" + (selected[p.id] ? " checked" : "") + " title='Select for sending to several printers'>" +
        "<span class='dot " + esc(status.needs_clearing ? "paused" : status.state) + "'" + fold + "></span>" +
        "<span class='card-title'" + fold + ">" + esc(p.name) + "</span></div>" +
        "<div class='row'><span class='small muted'" + fold + ">" + esc(stateText) + "</span>" +
        (fold ? iconButton("up", "data-collapse", p.id, "Collapse") : "") +
        iconButton("refresh", "data-refresh", p.id, "Refresh: ask this printer for its status now") +
        iconButton("edit", "data-edit", p.id, "Edit this printer") + "</div></div>" +
      lines + sendLine +
      "<div class='actions'>" +
        "<button type='button' class='quiet' data-upload='" + esc(p.id) + "'" + (uploadWhy ? " disabled" : "") + ">Upload</button>" +
        "<button type='button' data-start='" + esc(p.id) + "'" + (startWhy ? " disabled" : "") + ">Upload and print</button></div>" +
      (hint ? "<div class='small muted' style='margin-top:4px'>" + esc(hint) + "</div>" : "") +
      "</div>";
  }
  function renderPrinters() {
    $("empty").style.display = state.printers.length ? "none" : "block";
    var groups = { attention: [], available: [], busy: [] };
    state.printers.forEach(function (p) { groups[groupOf(p)].push(p); });
    var titles = { attention: "Needs attention", available: "Available", busy: "Busy" };
    $("printers").innerHTML = ["attention", "available", "busy"].map(function (name) {
      var list = groups[name];
      if (!list.length && (name === "attention" || !state.printers.length)) return "";
      var body = list.map(function (p) {
        var status = state.status[p.id] || { state: "unknown", state_text: "Checking..." };
        // A busy printer is one line, unless opened, selected or in the middle of a send.
        var slim = name === "busy" && !expanded[p.id] && !selected[p.id] && !(state.sends[p.id] && state.sends[p.id].active);
        return slim ? slimCard(p, status) : fullCard(p, status, name);
      }).join("");
      return "<div class='group'>" + titles[name] + " (" + list.length + ")</div>" +
             (body || "<div class='small muted' style='margin-top:5px'>" + (name === "available" ? "No printer is free right now." : "Nothing is printing.") + "</div>");
    }).join("");
  }

  // ---- stored files and cleanup ----------------------------------------------------------
  function megabytes(bytes) {
    var mb = (bytes || 0) / 1048576;
    return mb >= 1024 ? (mb / 1024).toFixed(1) + " GB" : Math.round(mb) + " MB";
  }
  function ageText(seconds) {
    if (!seconds) return "";
    var days = Math.floor((Date.now() / 1000 - seconds) / 86400);
    return days < 1 ? "today" : days + " d";
  }
  // Why old files cannot be removed from this printer right now. Mirrors the check in the plugin.
  function cleanBlock(p) {
    var status = state.status[p.id];
    if (!status || status.state === "unknown" || status.state === "offline") return "not reachable";
    if (p.kind === "elegoo_cc2" && status.state !== "idle") return "busy, cleaned when idle";
    if (state.sends[p.id] && state.sends[p.id].active) return "busy with a send";
    return "";
  }
  var counting = 0;   // printers still to answer after a recount was asked for
  function recount() {
    counting = state.printers.length;
    renderStorage();
    send("check_storage");
    setTimeout(function () { counting = 0; renderStorage(); }, 30000);   // never stuck on "Counting..."
  }
  function renderStorage() {
    $("storage").style.display = state.printers.length ? "block" : "none";
    var removable = 0;
    var rows = state.printers.map(function (p) {
      var st = state.storage[p.id];
      var detail;
      if (!st || st.count == null) detail = "<span class='muted'>" + esc(st && st.error ? st.error : "counting...") + "</span>";
      else {
        removable += st.removable || 0;
        detail = "<span class='" + (st.many ? "warn" : "muted") + "'>" + st.count + " file" + (st.count === 1 ? "" : "s") + " \u00b7 " + megabytes(st.bytes) +
                 (st.oldest ? " \u00b7 oldest " + ageText(st.oldest) : "") + "</span>" +
                 (st.removable ? " <span class='warn'>\u00b7 " + st.removable + " old</span>" : "");
      }
      return "<div class='row spread small' style='gap:8px;margin-top:3px'><span class='file'>" + esc(p.name) + "</span>" +
             "<span style='white-space:nowrap'>" + detail + "</span></div>";
    }).join("");
    $("storage").innerHTML =
      "<div class='row spread'><span class='card-title'>Stored files</span><div class='row'>" +
        "<span class='small muted'>" + (counting ? "Counting..." : "") + "</span>" +
        "<button type='button' class='icon' id='clean-refresh' title='Count the stored files on every printer again' aria-label='Count the stored files again'>" + svg("refresh") + "</button>" +
        "<button type='button' class='quiet' id='clean-open'" + (removable ? "" : " disabled") + ">Clean up" + (removable ? " (" + removable + ")" : "") + "</button></div></div>" +
      "<div class='row spread small muted' style='gap:8px;margin-top:2px'><span class='file'>Rule: " + esc(state.cleanup.text) +
        (state.cleanup.auto ? " \u00b7 automatic" : "") + "</span>" +
        "<button type='button' class='linkish' style='flex:none' id='clean-rule'>change</button></div>" + rows;
    $("clean-refresh").onclick = recount;
    $("clean-open").onclick = cleanupDialog;
    $("clean-rule").onclick = ruleDialog;
  }
  function ruleDialog() {
    var c = state.cleanup;
    showDialog("<h4>Which stored files to keep</h4>" +
      "<p class='small muted' style='margin:0 0 6px'>Files on the printers that fall outside the rule count as old. Nothing is deleted until you click Clean up, unless you tick automatic.</p>" +
      "<div class='check'><input type='radio' name='r-mode' id='r-age'" + (c.mode === "age" ? " checked" : "") + "><label for='r-age'>Keep files newer than</label>" +
        "<input id='r-days' type='number' min='1' max='3650' style='width:64px' value='" + esc(c.days) + "'><span>days</span></div>" +
      "<div class='check' style='margin-top:8px'><input type='radio' name='r-mode' id='r-count'" + (c.mode === "count" ? " checked" : "") + "><label for='r-count'>Keep the newest</label>" +
        "<input id='r-keep' type='number' min='1' max='5000' style='width:64px' value='" + esc(c.keep) + "'><span>files</span></div>" +
      "<div class='check' style='margin-top:12px'><input type='checkbox' id='r-auto'" + (c.auto ? " checked" : "") + "><label for='r-auto'>Clean automatically, once a day</label></div>" +
      "<p class='small muted' style='margin:4px 0 0'>Automatic cleanup only runs while this panel is open. The file being printed is always kept, and a Centauri Carbon 2 is only cleaned while idle.</p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button><button type='button' id='dlg-ok'>Save</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      send("save_cleanup", { rule: { mode: $("r-count").checked ? "count" : "age", days: parseInt($("r-days").value, 10) || c.days,
                                     keep: parseInt($("r-keep").value, 10) || c.keep, auto: $("r-auto").checked } });
      hideDialog();
    };
  }
  function cleanupDialog() {
    var total = 0;
    var rows = state.printers.map(function (p) {
      var st = state.storage[p.id] || {}, n = st.removable || 0, why = cleanBlock(p);
      if (!n) return "";
      if (!why) total += n;
      return "<div class='check'><input type='checkbox' data-clean='" + esc(p.id) + "' data-count='" + n + "' id='cl-" + esc(p.id) + "'" +
             (why ? " disabled" : " checked") + "><label for='cl-" + esc(p.id) + "'>" + esc(p.name) + ": " + n + " old file" + (n === 1 ? "" : "s") +
             (why ? " <span class='muted'>(" + esc(why) + ")</span>" : "") + "</label></div>";
    }).join("");
    showDialog("<h4>Remove old files from the printers?</h4>" +
      "<p class='small' style='margin:0 0 8px'>Rule: " + esc(state.cleanup.text) + ". The file a printer is printing is always kept.</p>" + rows +
      "<p class='small warn' style='margin:10px 0 0'>Deleted files cannot be brought back.</p>" +
      "<div class='dialog-actions'><button type='button' class='quiet' id='dlg-cancel'>Cancel</button>" +
      "<button type='button' class='danger' id='dlg-ok'" + (total ? "" : " disabled") + ">Delete old files</button></div>");
    $("dlg-cancel").onclick = hideDialog;
    $("dlg-ok").onclick = function () {
      var ids = [];
      Array.prototype.forEach.call($("dialog").querySelectorAll("input[data-clean]"), function (box) { if (box.checked && !box.disabled) ids.push(box.dataset.clean); });
      if (ids.length) send("cleanup", { printer_ids: ids });
      hideDialog();
    };
  }

  function render() { renderJob(); renderMulti(); renderPrinters(); renderStorage(); }

  function byId(id) { return state.printers.filter(function (p) { return p.id === id; })[0]; }

  $("printers").addEventListener("click", function (event) {
    var t = event.target, d = t.dataset || {};
    if (d.upload) confirmSend([byId(d.upload)], false);
    else if (d.start) confirmSend([byId(d.start)], true);
    else if (d.refresh) refresh([d.refresh]);
    else if (d.cleared) bedCleared(d.cleared);
    else if (d.collapse) { delete expanded[d.collapse]; renderPrinters(); }
    else if (d.expand) { expanded[d.expand] = true; renderPrinters(); }
    else if (d.edit) editPrinter(byId(d.edit));
    else if (d.cancel) send("cancel_send", { id: d.cancel });
    else if (d.pick) { selected[d.pick] = t.checked; renderMulti(); renderPrinters(); }
  });
  $("btn-add").onclick = function () { editPrinter(null); };
  $("btn-refresh").onclick = function () { refresh(state.printers.map(function (p) { return p.id; })); recount(); };
  $("btn-import").onclick = function () { send("import_presets"); };

  orca.onMessage(function (message) {
    if (!message) return;
    if (message.command === "state") {
      ["printers", "jobs", "job_for", "slicing", "combos", "types", "library", "folders", "orders", "order_plates", "toolhead_names", "current", "combo_note", "can_switch", "storage", "cleanup"].forEach(function (key) { if (key in message) state[key] = message[key]; });
      if (message.status) state.status = message.status;
      if (message.sends) state.sends = message.sends;
      render();
    } else if (message.command === "status") {
      delete refreshing[message.id];
      state.status[message.id] = message.status; renderMulti(); renderPrinters(); renderStorage();
    } else if (message.command === "order_plan") {
      showPlan(message);
    } else if (message.command === "library_result") {
      if (message.ok) { hideDialog(); libNote = message.text ? { ok: true, text: message.text } : null; plateView = "library"; renderJob(); }
      else if ($("l-result")) { $("l-result").className = "small err"; $("l-result").textContent = message.text; }
    } else if (message.command === "storage") {
      if (counting > 0) counting -= 1;
      state.storage[message.id] = message.storage; renderStorage(); renderPrinters();
    } else if (message.command === "send") {
      if (message.send) state.sends[message.id] = message.send; else delete state.sends[message.id];
      renderMulti(); renderPrinters();
    } else if (message.command === "form_result") {
      var out = $("f-result");
      if (message.saved) { hideDialog(); return; }
      if (!out) return;
      out.className = "small " + (message.ok ? "ok" : "err");
      out.textContent = message.text;
      if (message.model && $("f-model") && !$("f-model").value) $("f-model").value = message.model;
    } else if (message.command === "import_result") {
      var rows = (message.added || []).map(function (n) { return "<li>" + esc(n) + "</li>"; }).join("");
      showDialog("<h4>Import from printer presets</h4><p>" + esc(message.text) + "</p>" + (rows ? "<ul class='plain'>" + rows + "</ul>" : "") +
        "<div class='dialog-actions'><button type='button' id='dlg-ok'>OK</button></div>");
      $("dlg-ok").onclick = hideDialog;
    }
  });

  send("init");
  setInterval(function () { send("poll"); }, 4000);
})();
</script>
"""


# ======================================================================================
# plugin
PLUGIN_TITLE = "Farm Send"


def _data_dir_from_file():
    """OrcaSlicer's data folder, derived from where this file is installed."""
    try:
        return data_dir_of(__file__)
    except NameError:
        return ""


def _gcode_temp_trees():
    """Folders OrcaSlicer writes the per-plate G-code into after a slice.

    2.5 uses a per-user temp root, <tmp>/orcaslicer_<uid>/orcaslicer_model; earlier builds wrote
    straight to <tmp>/orcaslicer_model. Both are declared so one prompt at load covers either."""
    temp = tempfile.gettempdir()
    trees = [os.path.join(temp, "orcaslicer_model", "*")]
    if hasattr(os, "getuid"):
        trees.insert(0, os.path.join(temp, "orcaslicer_%d" % os.getuid(), "orcaslicer_model", "*"))
    return trees


def _saved_hosts():
    """Printer hosts saved by an earlier run, read without the plugin storage API because that API
    only works inside a capability call and permissions are declared before any exists."""
    base = _data_dir_from_file()
    if not base:
        return []
    hosts = set()
    try:
        plugin_file = __file__
    except NameError:
        plugin_file = ""
    for path in saved_store_files(base, plugin_file):
        hosts.update(PrinterStore(path).hosts())
    return sorted(hosts)


class FarmSend(orca.script.ScriptPluginCapabilityBase):
    panel = None
    pool = None
    app = None

    def get_name(self):
        return PLUGIN_TITLE

    # ---- wiring ------------------------------------------------------------------------------
    def _start_workers(self):
        """Start the background workers. Only called from execute(), where OrcaSlicer knows this
        plugin is the one running; never from a panel message."""
        if self.pool is None:
            self.pool = WorkerPool()
        self.pool.start()

    def _ensure_app(self):
        if self.pool is None:
            self.pool = WorkerPool()
        if self.app is None:
            storage = orca.host.plugin.storage()
            self.app = FarmApp(storage, self._post, self._notify, (), self._default_name,
                               read_presets=self._read_presets, apply_presets=self._apply_presets,
                               list_presets=self._list_printer_presets, spawn=self.pool.submit)
        return self.app

    def _post(self, message):
        panel = self.panel
        if panel is not None:
            panel.post(message)

    def _notify(self, level, text):
        levels = orca.host.ui.NotificationLevel
        kind = levels.ErrorNotificationLevel if level == "error" else levels.RegularNotificationLevel
        try:
            orca.host.ui.push_notification(kind, text)
        except Exception:
            pass

    def _default_name(self):
        # Only called from panel messages, which run on the UI thread where the model is safe to read.
        try:
            objects = orca.host.model().objects()
            return objects[0].name if objects else ""
        except Exception:
            return ""

    def _read_presets(self):
        # UI thread only (panel messages).
        bundle = orca.host.preset_bundle()
        printer = bundle.current_printer_preset()
        return {
            "model": printer.config_value("printer_model") or "",
            "printer": printer.name,
            "process": bundle.current_process_preset().name,
            "filaments": list(bundle.current_filament_preset_names()),
        }

    def _list_printer_presets(self):
        """The user's printer presets as OrcaSlicer has them loaded right now. UI thread only.

        Asked from OrcaSlicer, not read from preset files: a signed-in user has two preset
        folders on disk and only OrcaSlicer knows which one is in use."""
        printers = orca.host.preset_bundle().printers
        found = []
        for index in range(printers.size()):
            preset = printers.preset(index)
            if not preset.is_user():
                continue
            entry = {"name": preset.name}
            for key in ("print_host", "printhost_apikey", "host_type", "printer_model", "inherits", "nozzle_diameter"):
                entry[key] = preset.config_value(key)
            found.append(entry)
        return found

    def _apply_presets(self, combo):
        """Switch OrcaSlicer to a saved printer/filament/process selection.

        Runs on a plugin thread, never the UI thread: each call hands the selection to the UI thread
        and waits, including for OrcaSlicer's own save/discard dialog when a preset has unsaved
        edits. begin_update() is used only for its selection step; nothing is staged or committed.
        Printer first, because it decides which filaments and processes can be chosen.
        Returns the parts that could not be applied; raises if the printer could not be selected."""
        skipped = []
        orca.host.preset.printer.begin_update(preset_name=combo["printer"])
        for index, name in enumerate(combo.get("filaments") or []):
            try:
                orca.host.preset.filament.begin_update(index + 1, name)
            except IndexError:
                break      # this printer selection has fewer filament slots than were saved
            except (ValueError, RuntimeError) as error:
                skipped.append("filament %d (%s)" % (index + 1, str(error).splitlines()[0][:120]))
        if combo.get("process"):
            try:
                orca.host.preset.process.begin_update(preset_name=combo["process"])
            except (ValueError, RuntimeError) as error:
                skipped.append("process (%s)" % str(error).splitlines()[0][:120])
        return skipped

    # ---- capability entry points -------------------------------------------------------------
    def execute(self):
        self._start_workers()
        self._ensure_app()
        if self.panel is not None and self.panel.is_open():
            self.panel.show()
            return orca.ExecutionResult.success("Farm Send is already open.")
        self.panel = orca.host.ui.create_dock_panel(
            html=PANEL_HTML, title=PLUGIN_TITLE, width=340, height=560,
            on_message=self._on_message, on_close=self._on_close, dock="right")
        return orca.ExecutionResult.success("Farm Send opened.")

    def _on_message(self, message):
        try:
            self._ensure_app().handle(message)
        except Exception as error:
            self._notify("error", "Farm Send: %s" % error)

    def _on_close(self):
        self.panel = None

    def on_lifecycle_event(self, event, ctx):
        # Slice events arrive on the slicing worker thread. Nothing here may wait on the UI thread.
        events = orca.LifecycleEvent
        try:
            if event == events.GCodeExportFinished:
                app = self._ensure_app()
                if ctx.code == orca.LifecycleEvtCode.Ok:
                    app.on_gcode_exported(ctx.msg, ctx.name)
                else:
                    app.on_slice_done()
            elif self.app is None:
                return
            elif event == events.SliceStarted:
                self.app.on_slice_started()
            elif event == events.SlicingJobComplete:
                self.app.on_slice_done()
            elif event in (events.ObjectAdded, events.ObjectDeleted, events.ObjectTransformed, events.ObjectChanged):
                # Preset changes are deliberately not treated as "plate changed": switching presets
                # is exactly what happens between slicing for one printer type and the next.
                self.app.mark_stale()
            elif event in (events.ProjectClosed, events.NewProject, events.ProjectOpened):
                self.app.project_closed()
        except Exception:
            pass


@orca.plugin
class FarmSendPlugin(orca.base):
    def register_capabilities(self):
        hosts = ["http://" + host for host in _saved_hosts()]
        orca.request_permissions(fs_read=_gcode_temp_trees(), network=hosts, threading=True)
        orca.register_capability(FarmSend)
